async () => {
const out=[];
for(let p=1;p<=17;p++){
 if(p>1){ const f=document.forms[0]; const link=[...document.querySelectorAll('a')].find(a=>a.getAttribute('href')==="javascript:__doPostBack('gv','Page$"+p+"')"); if(!link){out.push('nolink '+p);continue;}
  const r=await fetch(location.href,{method:'POST',body:new URLSearchParams([...new FormData(f)].filter(([k])=>!['__EVENTTARGET','__EVENTARGUMENT'].includes(k)).concat([['__EVENTTARGET','gv'],['__EVENTARGUMENT','Page$'+p]]))});
  const t=await r.text(); const d=new DOMParser().parseFromString(t,'text/html');
  d.querySelectorAll('tr').forEach(tr=>{const c=[...tr.children].map(x=>x.innerText??x.textContent); if(/^D\d+/.test((c[1]||'').trim())) out.push(c.slice(0,4).map(s=>s.trim()).join(','))});
 }
}
return out.join('\n');}

