async () => {
async function all(url,rx){
 const out=[]; let r=await fetch(url); let t=await r.text();
 for(let p=1;p<=20;p++){
  const d=new DOMParser().parseFromString(t,'text/html');
  d.querySelectorAll('tr').forEach(tr=>{const c=[...tr.children].map(x=>x.textContent.trim()); if(rx.test(c[1]||'')) out.push(c.slice(1,4).join(','))});
  const f=d.forms[0]; const has=[...d.querySelectorAll('a')].some(a=>(a.getAttribute('href')||'').includes("Page$"+(p+1)+"'"));
  if(!has) break;
  const fd=new FormData(f); fd.set('__EVENTTARGET','gv'); fd.set('__EVENTARGUMENT','Page$'+(p+1));
  t=await (await fetch(url,{method:'POST',body:new URLSearchParams(fd)})).text();
 } return out;}
const res=await all('/Residents.aspx',/^\S.* \S+$/);
const dev=await all('/Devices.aspx',/^D\d+$/);
return JSON.stringify({res:res.filter(s=>/,(1004|1011|1026|1003|1005|1010|1012),/.test(s)),nres:res.length,devFiltered:dev.filter(s=>/,(1004|1011|1026),/.test(s)),ndev:dev.length});}

